AWARD_RACES.push(['mip','Most Improved Player'],['coach','Coach of the Year']);
function improvedCandidates(rows){const production=r=>r&&r.gp>0&&['pts','reb','ast','stl','blk','tov'].every(k=>Number.isFinite(r[k]))?(r.pts+.7*r.reb+.7*r.ast+r.stl+r.blk-r.tov)/r.gp:null;return rows.filter(r=>!r.rookie).map(r=>{const old=(state.statsArchive||[]).find(p=>p.year===state.year-1&&p.id===r.id&&p.gp>=10),prior=production(old),now=production(r);return {...r,improvement:prior!==null&&now!==null?now-prior:null}}).filter(r=>r.improvement>0).sort((a,b)=>b.improvement-a.improvement||a.id-b.id).slice(0,5)}
function coachCandidates(){return state.teams.filter(t=>!expansionPendingSeason(t)&&t.w+t.l>0).map(t=>({id:t.id,club:t.id,name:coachFor(t).name,record:{w:t.w,l:t.l},rate:t.w/(t.w+t.l)})).sort((a,b)=>b.rate-a.rate||b.record.w-a.record.w||a.id-b.id).slice(0,5)}
const candidatesBeforeExtraAwards=awardCandidates;awardCandidates=function(type,rows=awardRaceRows()){return type==='coach'?coachCandidates():type==='mip'?improvedCandidates(rows):candidatesBeforeExtraAwards(type,rows)};
function finalizeRegularAwards(){
 if(state.day<seasonLength()||(state.regularAwards||[]).some(r=>r.year===state.year))return;
 const rows=awardRaceRows(),out={year:state.year};for(const [key,label] of AWARD_RACES){const winner=awardCandidates(key,rows)[0],t=winner&&state.teams[winner.club];out[key]=winner?{id:winner.id,name:winner.name,team:t.city+' '+t.name}:null;say(label.replace(' Watch','')+': '+(winner?winner.name+(key==='executive'?', '+t.city+' '+t.name:' ('+t.city+')'):'No eligible winner')+'.')}
 (state.regularAwards??=[]).push(out);
}
const awardsDayBeforeFinal=awardRaceDay;awardRaceDay=function(){awardsDayBeforeFinal();finalizeRegularAwards()};
const playoffsBeforeRegularAwards=playoffs;playoffs=function(){if(state.day===seasonLength()&&state.champion===null)finalizeRegularAwards();return playoffsBeforeRegularAwards()};
const honorsBeforeRegularAwards=seasonHonors;seasonHonors=function(){const honors=honorsBeforeRegularAwards();if(!honors)return honors;const regular=state.regularAwards?.find(r=>r.year===state.year);if(regular)for(const [key] of AWARD_RACES)honors[key]=regular[key]??null;return honors};
const leagueRowsBeforeRegularAwards=leagueHistoryRows;leagueHistoryRows=function(){const rows=leagueRowsBeforeRegularAwards().map(r=>({...r}));for(const r of state.regularAwards||[]){const old=rows.find(x=>x.year===r.year);if(!old)rows.push({...r});else for(const [key] of AWARD_RACES)old[key]=r[key]??null}return rows.sort((a,b)=>b.year-a.year)};
const awardViewBeforeExtra=awardRacesView;awardRacesView=function(){
 const type=awardRaceTab,final=state.regularAwards?.find(r=>r.year===state.year),winner=final?.[type],banner=final?`<section class="panel"><div class="panelhead"><h2>Regular-season award announced</h2></div><p class="note">${escapeHTML(AWARD_RACES.find(([k])=>k===type)[1].replace(' Watch',''))}: <strong>${winner?escapeHTML(winner.name):'No eligible winner'}</strong>${winner?' · '+escapeHTML(winner.team):''}</p></section>`:'';
 if(!['coach','mip'].includes(type))return banner+awardViewBeforeExtra();
 const rows=awardCandidates(type),coach=type==='coach';return banner+`<section class="panel"><div class="panelhead"><h2>${coach?'Coach of the Year':'Most Improved Player'}</h2><span>${final?'Final rankings':'Live projections'}</span></div><nav class="po-tabs" aria-label="Award races">${AWARD_RACES.map(([k,n])=>`<button onclick="switchAwardRace('${k}')" class="${k===type?'selected':''}">${n}</button>`).join('')}</nav><div class="scroll"><table><thead><tr><th>Rank</th><th>${coach?'Coach':'Player'}</th><th>Team</th><th>${coach?'Record':'PPG'}</th><th>${coach?'Win%':'Improvement'}</th><th>Trend</th></tr></thead><tbody>${rows.map((r,i)=>{const t=state.teams[r.club],trend=awardTrend(type,r.id,i);return `<tr><td>${i+1}</td><th><button class="namebutton" onclick="${coach?'openCoachProfile':'profile'}(${r.id})">${escapeHTML(r.name)}</button></th><td>${escapeHTML(t.city+' '+t.name)}</td><td>${coach?r.record.w+'–'+r.record.l:r.ppg.toFixed(1)}</td><td>${coach?(r.rate*100).toFixed(1)+'%':'+'+r.improvement.toFixed(1)}</td><td class="${trend.cls}" title="${trend.label}">${trend.text}</td></tr>`}).join('')||'<tr><td colspan="6">No eligible candidates yet.</td></tr>'}</tbody></table></div><h3 class="note">Eligibility & scoring</h3><p class="note">${coach?'Ranked by regular-season win percentage, then wins.':'Non-rookies with at least 10 games in the previous season and current award eligibility. Improvement compares per-game points + 0.7 rebounds + 0.7 assists + steals + blocks − turnovers. Missing previous-season data is not estimated.'}</p></section>`;
};
function postseasonSchedulePanel(){
 const league=scheduleSettings().audience==='league',games=state.history.map((g,index)=>({...g,index})).filter(g=>['First round','Conference semifinal','Conference final','Semifinal','Championship'].includes(g.stage)&&(league||g.a===scheduleTeamId()||g.b===scheduleTeamId()));
 const pending=state.champion===null?firstRoundPairs().filter(p=>league||p.includes(controlledTeamId())):[];
 const identity=id=>escapeHTML(state.teams[id].city+' '+state.teams[id].name);
 return `<section class="panel schedule-postseason"><div class="panelhead"><h2>Playoff schedule & results</h2></div><p class="note">${playoffField().length}-team tournament · Single elimination. The current engine simulates the tournament together.</p><div class="scroll"><table><thead><tr><th>Round</th><th>Home</th><th>Away</th><th>Result</th></tr></thead><tbody>${games.map(g=>`<tr><th>${g.stage}</th><td>${identity(g.a)}</td><td>${identity(g.b)}</td><td><button onclick="showResult(${g.index})">${g.sa}–${g.sb} · View results</button></td></tr>`).join('')}${pending.map(p=>`<tr><th>${usesConferencePlayoffs()?'First round':'Semifinal'}</th><td>${identity(p[0])}</td><td>${identity(p[1])}</td><td>Upcoming</td></tr>`).join('')}${state.champion===null&&league?'<tr><th>Championship</th><td>Conference / bracket 1 winner</td><td>Conference / bracket 2 winner</td><td>Awaiting earlier rounds</td></tr>':''}</tbody></table></div>${!games.length&&!pending.length&&!league?'<p class="note">Your team has no playoff games. Select Entire league to see the tournament.</p>':''}<button class="primary" onclick="${state.champion===null?'playoffs()':'newSeason()'}">${state.champion===null?'Simulate playoffs':'Continue offseason'}</button></section>`;
}
